//! Generated Rust client types for the OME (ome.io/v1beta1) CRDs.
//!
//! Generated by `kopium` (`--schema=disabled`) from the CRD YAML in
//! `config/crd/full/` — the same YAML `make manifests` produces from the Go
//! markers. Do NOT edit the per-CRD modules by hand; regenerate with
//! `make rust-client` (in `ome-client-rs/`). Editing them is pointless: the
//! next regeneration overwrites your change, and the types must track the Go
//! source of truth, not drift from it.
//!
//! Beyond the generated types, two optional, hand-written modules add the SDK
//! ergonomics — there is no client-go-style codegen for them because kube-rs is
//! generic: `client` (the [`client::OmeClient`] clientset) and `runtime`
//! ([`informers::shared_informer`] + `Store`, the informer/lister).

pub mod basemodels;
pub mod clusterbasemodels;
pub mod clusterservingruntimes;
pub mod finetunedweights;
pub mod inferencereplicas;
pub mod inferenceservices;
pub mod servingruntimes;
pub mod trafficmaps;
pub mod workloadclusters;

// Re-export the nine Kind types at the crate root. The Kind names are unique
// across the OME API group, so these flat re-exports never collide; the
// per-Kind spec/status/sub-structs stay namespaced under their module.
pub use basemodels::BaseModel;
pub use clusterbasemodels::ClusterBaseModel;
pub use clusterservingruntimes::ClusterServingRuntime;
pub use finetunedweights::FineTunedWeight;
pub use inferencereplicas::InferenceReplica;
pub use inferenceservices::InferenceService;
pub use servingruntimes::ServingRuntime;
pub use trafficmaps::TrafficMap;
pub use workloadclusters::WorkloadCluster;

// Re-export k8s-openapi so consumers get version-matched access to built-in kinds
// (e.g. `Node` for capacity views) and meta types (`LabelSelector`) without
// separately pinning k8s-openapi.
pub use k8s_openapi;

// Ergonomic SDK layer over the generated types + kube-rs generics (no codegen):
//   `client`  -> OmeClient: clientset-style typed Api<T> accessors.
//   `runtime` -> shared_informer + Store<T>: the informer/lister helpers.
#[cfg(feature = "client")]
pub mod client;
#[cfg(feature = "runtime")]
pub mod informers;
#[cfg(feature = "runtime")]
pub mod listers;
